public List<OrderFlatDto> findAllByDtoFlat() {
    return em.createQuery(
            "select new jpabook.jpashop.repository.order.query" +
            ".OrderFlatDto(o.id, m.name, o.orderDate, o.status, d.address," +
            " i.name, oi.orderPrice, oi.count)" +
            " from Order o" +
            " join o.member m" +
            " join o.delivery d" +
            " join o.orderItems oi" +
            " join oi.item i", OrderFlatDto.class)
        .getResultList();
}

public List<OrderQueryDto> findAllByDtoFlatFolded() {
    List<OrderFlatDto> flats = findAllByDtoFlat();

    return flats.stream()
        .collect(groupingBy(
            o -> new OrderQueryDto(o.getOrderId(), o.getName(),
                    o.getOrderDate(), o.getOrderStatus(), o.getAddress()),
            mapping(o -> new OrderItemQueryDto(o.getOrderId(),
                    o.getItemName(), o.getOrderPrice(), o.getCount()),
                toList())
        )).entrySet().stream()
        .map(e -> new OrderQueryDto(e.getKey().getOrderId(),
                e.getKey().getName(), e.getKey().getOrderDate(),
                e.getKey().getOrderStatus(), e.getKey().getAddress(),
                e.getValue()))
        .toList();
}
